package com.veljkoni.chessko.logic

object Loc {
    private var currentLanguage: String = "sr"

    fun setLanguage(code: String) {
        currentLanguage = code
        // For Chinese, we support zh-Hans as stored in xcstrings
        if (code == "zh") {
            currentLanguage = "zh-Hans"
        }
    }

    fun getLanguage(): String {
        return if (currentLanguage == "zh-Hans") "zh" else currentLanguage
    }

    /// Kod u obliku u kome se pojavljuje u IMENIMA FAJLOVA
    /// (`board-and-pieces.zh-Hans.json`). Razlikuje se od `getLanguage()`, koji
    /// za kineski vraca „zh" radi UI biraca. Lekcije se traze OVIM kodom —
    /// inace kineski korisnik tiho dobija engleski.
    fun fileLanguageCode(): String = currentLanguage

    fun get(key: String): String {
        val langMap = dictionary[key] ?: return key
        return langMap[currentLanguage] ?: langMap["en"] ?: key
    }

    fun format(key: String, vararg args: Any): String {
        val translatedPattern = get(key)
        return try {
            String.format(translatedPattern, *args)
        } catch (e: Exception) {
            translatedPattern
        }
    }

    /// Samo za testove: `dictionary` je private, a test mora da proveri da
    /// nijedan unos nije krnj. Bez ovoga bi test morao da zna svaki kljuc
    /// unapred, pa bi propustio bas one koji se naknadno dodaju.
    internal val dictionaryForTests: Map<String, Map<String, String>> get() = dictionary

